import { Server } from '@modelcontextprotocol/sdk/server/index.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import { SSEServerTransport } from '@modelcontextprotocol/sdk/server/sse.js';
import { config } from './config/index.js';
import { logger } from './utils/logger.js';
import { registerTools } from './tools/index.js';

export class GetNotesMCPServer {
  constructor(options = {}) {
    this.options = {
      transport: options.transport || 'stdio', // stdio, sse, http
      port: options.port || 3000,
      host: options.host || 'localhost',
      ...options
    };
    
    this.server = new Server(
      {
        name: config.server.name,
        version: config.server.version,
      },
      {
        capabilities: {
          tools: {},
          logging: {},
        },
      }
    );
    
    this.transport = null;
  }

  async start() {
    try {
      logger.info(`Starting ${config.server.name} v${config.server.version}...`);
      logger.info(`Transport mode: ${this.options.transport}`);
      
      // 注册工具
      await registerTools(this.server);
      
      // 设置错误处理
      this.server.onerror = (error) => {
        logger.error('Server error:', error);
      };
      
      // 设置关闭处理
      this.setupGracefulShutdown();
      
      // 根据传输模式启动
      switch (this.options.transport) {
        case 'stdio':
          await this.startStdio();
          break;
        case 'sse':
          await this.startSSE();
          break;
        case 'http':
          await this.startHTTP();
          break;
        default:
          throw new Error(`Unsupported transport mode: ${this.options.transport}`);
      }
      
      logger.info(`${config.server.name} started successfully`);
      logger.info(`API Base URL: ${config.api.baseURL}`);
      logger.info(`Tools registered: ${Object.keys(this.server._requestHandlers || {}).length}`);
      
      if (this.options.transport !== 'stdio') {
        logger.info(`Server listening on ${this.options.host}:${this.options.port}`);
      }
      
    } catch (error) {
      logger.error('Failed to start server:', error);
      process.exit(1);
    }
  }

  async startStdio() {
    // 在STDIO模式下禁用控制台日志，避免污染JSON输出
    process.env.MCP_TRANSPORT = 'stdio';
    logger.info('Starting STDIO transport...');
    this.transport = new StdioServerTransport();
    await this.server.connect(this.transport);
  }

  async startSSE() {
    logger.info(`Starting SSE transport on ${this.options.host}:${this.options.port}...`);
    
    // Import HTTP server modules only when needed
    const http = await import('http');
    const express = await this.getExpress();
    
    const app = express();
    
    // 基础路由
    app.get('/health', (req, res) => {
      res.json({ status: 'ok', server: config.server.name, version: config.server.version });
    });
    
    app.get('/tools', (req, res) => {
      res.json({ tools: this.server.getTools() });
    });
    
    // SSE端点
    app.get('/sse', async (req, res) => {
      const transport = new SSEServerTransport('/message', res);
      this.transport = transport;
      await this.server.connect(transport);
    });
    
    // 消息端点
    app.post('/message', express.json(), async (req, res) => {
      if (this.transport) {
        await this.transport.handlePostMessage(req, res);
      } else {
        res.status(503).json({ error: 'Server not ready' });
      }
    });
    
    const server = http.createServer(app);
    await new Promise((resolve) => {
      server.listen(this.options.port, this.options.host, resolve);
    });
    
    this.httpServer = server;
  }

  async startHTTP() {
    logger.info(`Starting HTTP transport on ${this.options.host}:${this.options.port}...`);
    
    const http = await import('http');
    const express = await this.getExpress();
    
    const app = express();
    app.use(express.json());
    
    // 健康检查
    app.get('/health', (req, res) => {
      res.json({ 
        status: 'ok', 
        server: config.server.name, 
        version: config.server.version,
        transport: 'http'
      });
    });
    
    // 获取工具列表
    app.get('/tools', (req, res) => {
      res.json({ tools: this.server.getTools() });
    });
    
    // 工具调用端点
    app.post('/tools/call', async (req, res) => {
      try {
        const { tool, arguments: args } = req.body;
        const result = await this.server.callTool(tool, args);
        res.json({ result });
      } catch (error) {
        logger.error('Tool call error:', error);
        res.status(500).json({ 
          error: error.message,
          type: error.name 
        });
      }
    });
    
    // MCP协议端点
    app.post('/mcp', async (req, res) => {
      try {
        const result = await this.server.handleRequest(req.body);
        res.json(result);
      } catch (error) {
        logger.error('MCP request error:', error);
        res.status(500).json({ 
          error: error.message,
          type: error.name 
        });
      }
    });
    
    const server = http.createServer(app);
    await new Promise((resolve) => {
      server.listen(this.options.port, this.options.host, resolve);
    });
    
    this.httpServer = server;
  }

  async getExpress() {
    try {
      const { default: express } = await import('express');
      return express;
    } catch (error) {
      logger.error('Express not found. Please install express for HTTP/SSE transport:');
      logger.error('npm install express');
      throw error;
    }
  }

  setupGracefulShutdown() {
    const shutdown = async (signal) => {
      logger.info(`Received ${signal}, shutting down...`);
      await this.stop();
      process.exit(0);
    };
    
    process.on('SIGINT', () => shutdown('SIGINT'));
    process.on('SIGTERM', () => shutdown('SIGTERM'));
    
    // Handle uncaught errors
    process.on('uncaughtException', (error) => {
      logger.error('Uncaught exception:', error);
      shutdown('uncaughtException');
    });
    
    process.on('unhandledRejection', (reason, promise) => {
      logger.error('Unhandled rejection at:', promise, 'reason:', reason);
      shutdown('unhandledRejection');
    });
  }

  async stop() {
    try {
      logger.info('Stopping server...');
      
      if (this.server) {
        await this.server.close();
      }
      
      if (this.httpServer) {
        await new Promise((resolve) => {
          this.httpServer.close(resolve);
        });
      }
      
      logger.info('Server stopped');
    } catch (error) {
      logger.error('Error stopping server:', error);
    }
  }
}